/**
 * Compile a {@link NodeStructureTemplate} + {@link NodeStylingTemplate} +
 * bindings + a node's data + the active palette into a concrete `NodeStyle`
 * fragment the {@link GraphLayer} merges into the node's resolved style.
 *
 * - **simple** → label text/colour/typography + shape + fill/stroke fields.
 * - **card** → a `composite` shape (`CompositeShapeOption`) with parts laid out
 *   by a small auto-layout pass, plus `bgStrokeWidth: 0` so the layer's base
 *   node border doesn't double up on the card frame.
 *
 * Every colour role is resolved to a number here (or falls back to a direct
 * colour, then to a neutral) — nothing role-shaped escapes to the renderer.
 */

import type { CompositePart, CompositeRootSpec } from '@invana/canvas';

import type { ColorRole } from '../theme/types';
import type { RolePalette } from '../theme/roles';
import type { GraphNode } from '../store/types';
import type { CompositeShapeOption, NodeBadge, NodeStyle } from '../layer/types';
import { resolvePath, resolveText } from './bindings';
import type {
  CardElement,
  CardSlot,
  CardStructure,
  CompositeFrame,
  FreeformStructure,
  NodeBadgeTemplate,
  NodeStylingTemplate,
  SimpleStructure,
  SlotStyling,
  TemplateColor,
  ValueLookup,
} from './types';

/** Solid stroke payload for a composite root shape. */
type RootStroke = { color: number; width: number };

/**
 * Map an authoring {@link CompositeFrame} (+ the card box, corner radius, and
 * resolved fill/stroke) to a concrete engine {@link CompositeRootSpec}. The
 * engine composite borrows a real shape for its silhouette, so there's no
 * geometry to duplicate here — only the box-fit policy:
 *   - `rect`            → rounded rectangle filling the box
 *   - `ellipse`         → ellipse inscribed in the box
 *   - `regular-polygon` → n-gon centred in the box (circum-radius = min/2)
 *   - `polygon`         → the normalised points mapped to centre-relative coords
 */
function frameToRoot(
  frame: CompositeFrame,
  width: number,
  height: number,
  cornerRadius: number,
  fill: number,
  stroke: RootStroke | undefined,
): CompositeRootSpec {
  const base = { x: 0, y: 0, fill, ...(stroke ? { stroke } : {}) };
  switch (frame.kind) {
    case 'rect':
      return { kind: 'rect', ...base, width, height, cornerRadius };
    case 'ellipse':
      return { kind: 'ellipse', ...base, radiusX: width / 2, radiusY: height / 2 };
    case 'regular-polygon':
      return {
        kind: 'regular-polygon',
        ...base,
        radius: Math.min(width, height) / 2,
        sides: frame.sides,
        ...(frame.rotation !== undefined ? { rotation: frame.rotation } : {}),
      };
    case 'polygon':
      return {
        kind: 'polygon',
        ...base,
        // Normalised [0,1] box points → centre-relative (PolygonSpec convention).
        vertices: frame.points.map((p) => ({ x: (p.x - 0.5) * width, y: (p.y - 0.5) * height })),
      };
  }
}

/** Resolve a colour pair (role wins, else direct, else `undefined`). */
function color(
  role: ColorRole | undefined,
  direct: number | undefined,
  palette: RolePalette,
): number | undefined {
  if (role !== undefined) {
    const v = palette[role];
    if (v !== undefined) return v;
  }
  return direct;
}

// ─── Value lookups + interpolation ────────────────────────────────────────────

/** `{}` (the bound value) or `{dotted.path}` (any other field of the record). */
const BIND_TOKEN = /\{([^{}]*)\}/g;

/**
 * Substitute `{}` / `{dotted.path}` tokens against a record.
 *
 * One rule, used by every template string — a badge's label and a card text
 * element — so `'{}%'` and `'L{data.lineRange.0}–{data.lineRange.1}'` are the
 * same feature rather than two syntaxes. A string with no braces passes
 * through untouched, which is what keeps every existing literal working.
 */
export function interpolate(template: string, node: GraphNode, bound?: unknown): string {
  if (!template.includes('{')) return template;
  return template.replace(BIND_TOKEN, (_match, path: string) =>
    path === ''
      ? bound === undefined || bound === null
        ? ''
        : String(bound)
      : resolveText(node, path),
  );
}

/** First band whose half-open interval contains `value`; declaration order wins. */
function matchBand<T>(bands: readonly { from?: number; to?: number; value: T }[], value: number): T | undefined {
  for (const band of bands) {
    if (band.from !== undefined && value < band.from) continue;
    if (band.to !== undefined && value >= band.to) continue;
    return band.value;
  }
  return undefined;
}

/**
 * Resolve a {@link ValueLookup} against a record: the categorical `map` first,
 * then the numeric `bands`, then `fallback`. `undefined` when nothing matched,
 * so the caller keeps whatever it already had.
 *
 * `fallbackBind` lets a lookup inherit the bind of the thing it sits on (a
 * badge's own `bind`), so the common case names the field once.
 */
export function resolveLookup<T>(
  lookup: ValueLookup<T> | undefined,
  node: GraphNode,
  fallbackBind?: string,
): T | undefined {
  if (!lookup) return undefined;
  const path = lookup.bind ?? fallbackBind;
  const value = path !== undefined ? resolvePath(node, path) : undefined;
  if (lookup.map && value !== undefined && value !== null) {
    const hit = lookup.map[String(value)];
    if (hit !== undefined) return hit;
  }
  if (lookup.bands && typeof value === 'number') {
    const hit = matchBand(lookup.bands, value);
    if (hit !== undefined) return hit;
  }
  return lookup.fallback;
}

/** A {@link TemplateColor} — literal number or role name — against the palette. */
function templateColor(value: TemplateColor | undefined, palette: RolePalette): number | undefined {
  if (value === undefined) return undefined;
  return typeof value === 'number' ? value : palette[value];
}

/**
 * Colour for one element: the record-driven lookup first, then the element's
 * own `*Role` / literal pair. A lookup that matches nothing falls through, so
 * the pair is the honest fallback rather than a hole.
 */
function lookupColor(
  lookup: ValueLookup<TemplateColor> | undefined,
  role: ColorRole | undefined,
  direct: number | undefined,
  node: GraphNode,
  palette: RolePalette,
): number | undefined {
  const hit = templateColor(resolveLookup(lookup, node), palette);
  if (hit !== undefined) return hit;
  return color(role, direct, palette);
}

/**
 * Resolve a template's `size` — a flat number, or a {@link ValueLookup} over a
 * second field. See {@link NodeStylingTemplate.size} for why this composes with
 * a type binding's structure instead of fighting it.
 */
export function compileSize(
  size: number | ValueLookup<number> | undefined,
  node: GraphNode,
): number | undefined {
  if (size === undefined) return undefined;
  return typeof size === 'number' ? size : resolveLookup(size, node);
}

// ─── Badges ───────────────────────────────────────────────────────────────────

/**
 * Does this template produce a badge for this record?
 *
 * An unbound template always does (a static per-type badge). A bound one needs
 * its field to be **present** — `undefined` / `null` means "no badge", which is
 * what lets a coverage pill vanish on the files the analyser had no figure for
 * — and then has to satisfy every `when*` clause that was declared. `0` and
 * `''` are values, not absences.
 */
function badgeApplies(t: NodeBadgeTemplate, value: unknown): boolean {
  if (t.bind === undefined) return true;
  if (value === undefined || value === null) return false;
  if (t.whenEquals !== undefined && value !== t.whenEquals) return false;
  if (t.whenGreaterThan !== undefined && !(typeof value === 'number' && value > t.whenGreaterThan)) {
    return false;
  }
  if (t.whenLessThan !== undefined && !(typeof value === 'number' && value < t.whenLessThan)) {
    return false;
  }
  return true;
}

/**
 * Compile a styling template's {@link NodeBadgeTemplate} list into the concrete
 * {@link NodeBadge} list for one node — bindings resolved, colours looked up
 * and roles substituted, and every badge whose bound field is absent dropped.
 *
 * Returns `undefined` when the template declares no badges (so the node
 * contributes nothing), and an **empty array** when it declares some and this
 * record matched none.
 */
export function compileBadges(
  styling: NodeStylingTemplate | undefined,
  node: GraphNode,
  palette: RolePalette,
): NodeBadge[] | undefined {
  const templates = styling?.badges;
  if (!templates || templates.length === 0) return undefined;

  const out: NodeBadge[] = [];
  for (const t of templates) {
    const value = t.bind !== undefined ? resolvePath(node, t.bind) : undefined;
    if (!badgeApplies(t, value)) continue;

    const {
      bind: _bind,
      whenEquals: _whenEquals,
      whenGreaterThan: _whenGreaterThan,
      whenLessThan: _whenLessThan,
      labelText,
      fill: _fill,
      fillRole: _fillRole,
      fillLookup: _fillLookup,
      strokeColor: _strokeColor,
      strokeColorRole: _strokeColorRole,
      labelColor: _labelColor,
      labelColorRole: _labelColorRole,
      ...geometry
    } = t;

    const badge: { -readonly [K in keyof NodeBadge]: NodeBadge[K] } = { ...geometry };

    // The badge's own `bind` is the lookup's default field, so a coverage pill
    // names `data.coverage` once and bands it here.
    const fill = templateColor(resolveLookup(t.fillLookup, node, t.bind), palette);
    badge.fill = fill ?? color(t.fillRole, t.fill, palette);
    if (badge.fill === undefined) delete badge.fill;
    const stroke = color(t.strokeColorRole, t.strokeColor, palette);
    if (stroke !== undefined) badge.strokeColor = stroke;
    const labelColor = color(t.labelColorRole, t.labelColor, palette);
    if (labelColor !== undefined) badge.labelColor = labelColor;

    const text =
      labelText !== undefined
        ? interpolate(labelText, node, value)
        : value === undefined || value === null
          ? ''
          : String(value);
    if (text !== '') badge.labelText = text;

    out.push(badge);
  }
  return out;
}

/** Compile a simple structure into label + shape + fill/stroke style fields. */
export function compileSimple(
  struct: SimpleStructure,
  styling: NodeStylingTemplate | undefined,
  bindings: Record<string, string>,
  node: GraphNode,
  palette: RolePalette,
): Partial<NodeStyle> {
  const out: Record<string, unknown> = { shape: struct.shape };

  const fill = color(styling?.fillRole, styling?.fill, palette);
  if (fill !== undefined) {
    // `fillAlpha` goes on the fill layer, never on `bgAlpha` — that one is the
    // whole shape's opacity and would fade the border with it, which is how a
    // tinted frame ends up looking borderless.
    out.bgFill =
      styling?.fillAlpha !== undefined
        ? { kind: 'solid', color: fill, alpha: styling.fillAlpha }
        : fill;
  }
  const stroke = color(styling?.strokeRole, styling?.stroke, palette);
  if (stroke !== undefined) {
    out.bgStrokeColor = stroke;
    out.bgStrokeWidth = styling?.strokeWidth ?? 1.5;
  } else if (styling?.strokeWidth !== undefined) {
    out.bgStrokeWidth = styling.strokeWidth;
  }
  if (styling?.strokeAlpha !== undefined) out.bgStrokeAlpha = styling.strokeAlpha;

  // Label
  const labelPath = bindings.label;
  if (labelPath) out.labelText = resolveText(node, labelPath);
  const lbl = styling?.label;
  if (lbl) {
    const lc = color(lbl.colorRole, lbl.color, palette);
    if (lc !== undefined) out.labelColor = lc;
    if (lbl.fontSize !== undefined) out.labelFontSize = lbl.fontSize;
    if (lbl.fontFamily !== undefined) out.labelFontFamily = lbl.fontFamily;
    if (lbl.fontWeight !== undefined) out.labelFontWeight = lbl.fontWeight;
    if (lbl.fontStyle !== undefined) out.labelFontStyle = lbl.fontStyle;
    if (lbl.placement !== undefined) out.labelPlacement = lbl.placement;
    if (lbl.offsetX !== undefined) out.labelOffsetX = lbl.offsetX;
    if (lbl.offsetY !== undefined) out.labelOffsetY = lbl.offsetY;
    if (lbl.rotation !== undefined) out.labelRotation = lbl.rotation;
    if (lbl.align !== undefined) out.labelAlign = lbl.align;
    if (lbl.background) {
      const bg = color(lbl.backgroundColorRole, lbl.backgroundColor, palette);
      if (bg !== undefined) out.labelBackgroundFill = bg;
    }
  }
  return out as Partial<NodeStyle>;
}

// ─── Card auto-layout ──────────────────────────────────────────────────────────

const DEFAULT_PAD = 14;
const ROW_GAP = 8;
const STACK_GAP = 2;

/** Per-slot resolved text styling, defaulted. */
interface ResolvedSlotStyle {
  fill: number;
  fontSize: number;
  fontWeight: number | string;
  fontFamily?: string;
  fontStyle?: 'normal' | 'italic';
  uppercase: boolean;
}

function resolveSlotStyle(
  slotStyle: SlotStyling | undefined,
  palette: RolePalette,
  fallbackRole: ColorRole,
): ResolvedSlotStyle {
  return {
    fill: color(slotStyle?.colorRole, slotStyle?.color, palette) ?? palette[fallbackRole] ?? 0x111111,
    fontSize: slotStyle?.fontSize ?? 13,
    fontWeight: slotStyle?.fontWeight ?? 400,
    fontFamily: slotStyle?.fontFamily,
    fontStyle: slotStyle?.fontStyle,
    uppercase: slotStyle?.uppercase ?? false,
  };
}

/** Compile a card structure into a `composite` shape option with laid-out parts. */
export function compileCard(
  struct: CardStructure,
  styling: NodeStylingTemplate | undefined,
  bindings: Record<string, string>,
  node: GraphNode,
  palette: RolePalette,
): Partial<NodeStyle> {
  const { width, height } = struct;
  const pad = struct.padding ?? DEFAULT_PAD;
  const inner = width - pad * 2;
  const parts: CompositePart[] = [];

  const bg = color(styling?.bgRole, styling?.bg, palette) ?? palette.cardBg ?? 0xffffff;
  // Card border. Read from the same `strokeRole` / `stroke` / `strokeWidth`
  // pair `compileSimple` and `compileFreeform` use, so one styling template
  // borders a card exactly as it borders a simple shape — a card used to be the
  // one structure kind that silently dropped them.
  const strokeColor = color(styling?.strokeRole, styling?.stroke, palette);
  const accent = color(styling?.accentRole, styling?.accent, palette);
  const dividerColor =
    color(styling?.slots?.divider?.colorRole, styling?.slots?.divider?.color, palette) ??
    palette.divider ??
    0xe2e8f0;

  // Optional accent bar down the left edge when an accent colour is configured.
  if (accent !== undefined) {
    parts.push({ part: 'rect', x: 0, y: 0, width: 4, height, fill: accent });
  }

  let y = pad;
  for (const row of struct.rows) {
    if (row.divider) {
      parts.push({
        part: 'line',
        x: pad,
        y,
        x2: width - pad,
        y2: y,
        stroke: { color: dividerColor, width: 1 },
      });
      y += ROW_GAP;
      continue;
    }
    if (!row.slots || row.slots.length === 0) {
      y += ROW_GAP;
      continue;
    }
    y = layoutRow(row.slots, parts, { x: pad, y, inner, pad, width }, styling, bindings, node, palette);
    y += ROW_GAP;
  }

  // The border rides the **composite's own** `stroke`, not the node-level
  // `bgStrokeColor`: it then traces whatever silhouette the card actually has
  // (a `frame` ellipse / polygon as readily as the default rounded rect), and
  // it survives the `bgStrokeWidth: 0` below, which exists to suppress a
  // *second*, rect-shaped border from the layer template.
  const rootStroke: RootStroke | undefined =
    strokeColor !== undefined ? { color: strokeColor, width: styling?.strokeWidth ?? 1 } : undefined;
  const shape: CompositeShapeOption = {
    kind: 'composite',
    width,
    height,
    cornerRadius: 10,
    // `root` and `stroke` are always stated, `undefined` when absent: the
    // renderer merges a shape update over the previous spec, so a key left out
    // keeps the last template's value (a rebind from a framed card to a plain
    // one would keep the old silhouette).
    root: struct.frame ? frameToRoot(struct.frame, width, height, 10, bg, rootStroke) : undefined,
    fill: bg,
    stroke: rootStroke,
    parts,
  };
  // Express the card background as the node's `bgFill` too (not only the
  // composite's internal fill). Styling owns the card colour, so this asserts it
  // at the node level — overriding any layer-wide colour-by-category default,
  // exactly as `compileSimple` does for simple shapes. `bgStrokeWidth: 0` stops
  // the layer's base node border from framing the card *on top of* the
  // silhouette-following stroke above.
  return { shape, bgFill: bg, bgStrokeWidth: 0 };
}

interface RowCursor {
  x: number;
  y: number;
  inner: number;
  pad: number;
  width: number;
}

/** Lay one row of cells left → right; returns the y cursor after the row. */
function layoutRow(
  slots: CardSlot[],
  parts: CompositePart[],
  cursor: RowCursor,
  styling: NodeStylingTemplate | undefined,
  bindings: Record<string, string>,
  node: GraphNode,
  palette: RolePalette,
): number {
  let x = cursor.x;
  let rowHeight = 0;

  // Right edge of the content box — every cell is clipped to it, and the last
  // cell of a multi-cell row is anchored *at* it.
  const rightEdge = cursor.width - cursor.pad;

  for (let i = 0; i < slots.length; i++) {
    const cell = slots[i]!;
    // Cells share the row instead of each claiming everything left of the right
    // edge. A cell used to take `rightEdge - x` and then advance `x` by the same
    // amount, so in a two-cell row (`symbol` + `package`) the first cell ate the
    // whole row and the second started **on** the right edge — drawing its text
    // outside the card. Split what's left evenly across the cells still to come.
    const available = rightEdge - x;
    const cellWidth = available / (slots.length - i);
    // The last cell of a multi-cell row right-aligns against the card's right
    // padding edge: that pairs a left tag with a right-hand qualifier (`CLASS` …
    // `@invana/graph`) the way the row reads, instead of leaving a ragged gap.
    const isTrailing = slots.length > 1 && i === slots.length - 1;
    if ('stack' in cell) {
      let sy = cursor.y;
      for (const sub of cell.stack) {
        if ('stack' in sub || sub.kind === 'image') continue; // stacks hold text/tag only
        const ss = resolveSlotStyle(styling?.slots?.[sub.slot], palette, 'foreground');
        const text = formatText(resolveText(node, bindings[sub.slot]), ss.uppercase);
        parts.push(label(text, x, sy + ss.fontSize, ss, cellWidth, 'left'));
        sy += ss.fontSize + STACK_GAP + 2;
      }
      rowHeight = Math.max(rowHeight, sy - cursor.y);
      x += cellWidth;
      continue;
    }
    if (cell.kind === 'image') {
      const size = cell.size ?? 40;
      const cx = x + size / 2;
      const cy = cursor.y + size / 2;
      // No photo support yet — render a coloured initials disc so the avatar
      // reads as a person (and stays legible on both light and dark cards),
      // rather than a near-invisible neutral placeholder.
      const discFill = palette.accent ?? palette.muted ?? 0xcbd5e1;
      if (cell.shape === 'rounded') {
        parts.push({ part: 'rect', x, y: cursor.y, width: size, height: size, cornerRadius: 8, fill: discFill });
      } else {
        parts.push({ part: 'circle', x: cx, y: cy, radius: size / 2, fill: discFill });
      }
      const initials = initialsOf(resolveText(node, bindings.title));
      if (initials) {
        const fontSize = Math.round(size * 0.4);
        parts.push({
          part: 'label',
          x: cx,
          y: cy - fontSize / 2,
          text: initials,
          anchor: 'center',
          fontSize,
          fontWeight: 700,
          fill: 0xffffff,
          maxLines: 1,
          overflow: 'ellipsis',
        });
      }
      x += size + 10;
      rowHeight = Math.max(rowHeight, size);
      continue;
    }
    // text | tag
    const ss = resolveSlotStyle(
      styling?.slots?.[cell.slot],
      palette,
      cell.kind === 'tag' ? 'muted' : 'heading',
    );
    const text = formatText(resolveText(node, bindings[cell.slot]), ss.uppercase);
    parts.push(
      isTrailing
        ? label(text, rightEdge, cursor.y + ss.fontSize, ss, cellWidth, 'right')
        : label(text, x, cursor.y + ss.fontSize, ss, cellWidth, 'left'),
    );
    x += cellWidth;
    rowHeight = Math.max(rowHeight, ss.fontSize + 2);
  }

  return cursor.y + (rowHeight || 14);
}

function formatText(text: string, uppercase: boolean): string {
  return uppercase ? text.toUpperCase() : text;
}

/** Initials for an avatar disc: first + last word's leading letter (e.g.
 * "Tim Berners-Lee" → "TL"), or the first two letters of a single word. */
function initialsOf(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return '';
  if (words.length === 1) return words[0]!.slice(0, 2).toUpperCase();
  return (words[0]![0]! + words[words.length - 1]![0]!).toUpperCase();
}

/** Build a composite `label` part with single-line ellipsis clipping. */
function label(
  text: string,
  x: number,
  baselineY: number,
  ss: ResolvedSlotStyle,
  maxWidth: number,
  anchor: 'left' | 'center' | 'right',
): CompositePart {
  return {
    part: 'label',
    x,
    y: baselineY,
    text,
    anchor,
    fontSize: ss.fontSize,
    fontWeight: ss.fontWeight,
    ...(ss.fontStyle ? { fontStyle: ss.fontStyle } : {}),
    fill: ss.fill,
    maxWidth,
    maxLines: 1,
    overflow: 'ellipsis',
  };
}

// ─── Free-form structure (the card designer's output) ───────────────────────

/**
 * Compile a {@link FreeformStructure} into a `composite` shape. Element
 * coordinates are already absolute (the designer canvas is 1:1 with the card),
 * so this is a direct map: bind text to data, resolve every colour role against
 * the palette, and emit one {@link CompositePart} per element. Self-contained —
 * no styling/binding template needed.
 */
export function compileFreeform(
  struct: FreeformStructure,
  node: GraphNode,
  palette: RolePalette,
): Partial<NodeStyle> {
  const bg = color(struct.bgRole, struct.bg, palette) ?? palette.cardBg ?? 0xffffff;
  // The silhouette's own colour may be read off the record — a card accented by
  // its cluster traces that colour round the whole frame, not just the bar.
  const strokeColor = lookupColor(
    struct.strokeLookup,
    struct.strokeRole,
    struct.stroke,
    node,
    palette,
  );
  const parts: CompositePart[] = [];

  for (const el of struct.elements) {
    if (el.hidden) continue;
    parts.push(...elementToParts(el, node, palette));
  }

  const rootStroke: RootStroke | undefined =
    strokeColor !== undefined ? { color: strokeColor, width: struct.strokeWidth ?? 1 } : undefined;
  const shape: CompositeShapeOption = {
    kind: 'composite',
    width: struct.width,
    height: struct.height,
    cornerRadius: struct.cornerRadius ?? 10,
    // Always stated, `undefined` when absent — see `compileCard`.
    root: struct.frame
      ? frameToRoot(struct.frame, struct.width, struct.height, struct.cornerRadius ?? 10, bg, rootStroke)
      : undefined,
    fill: bg,
    stroke: rootStroke,
    parts,
  };
  // Assert the card background at the node level too — styling owns the colour
  // and wins over any layer-wide colour-by-category default (see `compileCard`).
  return { shape, bgFill: bg, bgStrokeWidth: 0 };
}

/** Map one {@link CardElement} to its composite part(s). */
function elementToParts(el: CardElement, node: GraphNode, palette: RolePalette): CompositePart[] {
  // A presence rule, before anything is built: an element whose required field
  // is absent is not drawn at all, so an interpolated string never renders its
  // punctuation around nothing (`L–`).
  if (el.requires !== undefined) {
    const present = resolvePath(node, el.requires);
    if (present === undefined || present === null) return [];
  }
  switch (el.type) {
    case 'text': {
      // `text` wins when set and may interpolate `{}` (the bound value) or
      // `{dotted.path}`; `bind` alone renders the bound value verbatim.
      const bound = el.bind ? resolvePath(node, el.bind) : undefined;
      const raw =
        el.text !== undefined
          ? interpolate(el.text, node, bound)
          : el.bind
            ? resolveText(node, el.bind)
            : '';
      const text = el.uppercase ? raw.toUpperCase() : raw;
      const fill =
        lookupColor(el.colorLookup, el.colorRole, el.color, node, palette) ??
        palette.foreground ??
        0x111111;
      const wrap =
        el.maxWidth !== undefined
          ? { maxWidth: el.maxWidth, maxLines: el.maxLines ?? 1, overflow: 'ellipsis' as const }
          : {};
      return [
        {
          part: 'label',
          x: el.x,
          y: el.y + (el.fontSize ?? 13),
          text,
          anchor: el.anchor ?? 'left',
          fontSize: el.fontSize ?? 13,
          fontWeight: el.fontWeight ?? 400,
          ...(el.fontStyle ? { fontStyle: el.fontStyle } : {}),
          ...(el.fontVariant ? { fontVariant: el.fontVariant } : {}),
          ...(el.lineHeight !== undefined ? { lineHeight: el.lineHeight } : {}),
          ...(el.align ? { align: el.align } : {}),
          fill,
          ...wrap,
        },
      ];
    }
    case 'rect': {
      const fill = lookupColor(el.fillLookup, el.fillRole, el.fill, node, palette);
      const stroke = color(el.strokeRole, el.stroke, palette);
      return [
        {
          part: 'rect',
          x: el.x,
          y: el.y,
          width: el.width,
          height: el.height,
          ...(el.cornerRadius ? { cornerRadius: el.cornerRadius } : {}),
          ...(fill !== undefined ? { fill } : {}),
          ...(el.fillAlpha !== undefined ? { fillAlpha: el.fillAlpha } : {}),
          ...(stroke !== undefined ? { stroke: { color: stroke, width: el.strokeWidth ?? 1 } } : {}),
          ...(el.hitId !== undefined ? { hitId: el.hitId } : {}),
        },
      ];
    }
    case 'circle': {
      // `x`/`y` are the element's top-left (uniform with the designer canvas);
      // the composite `circle` part is centre-based.
      const fill = lookupColor(el.fillLookup, el.fillRole, el.fill, node, palette);
      const stroke = color(el.strokeRole, el.stroke, palette);
      return [
        {
          part: 'circle',
          x: el.x + el.radius,
          y: el.y + el.radius,
          radius: el.radius,
          ...(fill !== undefined ? { fill } : {}),
          ...(el.fillAlpha !== undefined ? { fillAlpha: el.fillAlpha } : {}),
          ...(stroke !== undefined ? { stroke: { color: stroke, width: el.strokeWidth ?? 1 } } : {}),
          ...(el.hitId !== undefined ? { hitId: el.hitId } : {}),
        },
      ];
    }
    case 'line': {
      const stroke =
        lookupColor(el.colorLookup, el.colorRole, el.color, node, palette) ??
        palette.divider ??
        0xe2e8f0;
      return [
        { part: 'line', x: el.x, y: el.y, x2: el.x2, y2: el.y2, stroke: { color: stroke, width: el.strokeWidth ?? 1 } },
      ];
    }
    case 'image': {
      // No composite image part yet — render a themed placeholder.
      const fill = palette.divider ?? 0xcccccc;
      if (el.shape === 'rounded') {
        return [{ part: 'rect', x: el.x, y: el.y, width: el.size, height: el.size, cornerRadius: 8, fill }];
      }
      const r = el.size / 2;
      return [{ part: 'circle', x: el.x + r, y: el.y + r, radius: r, fill }];
    }
    case 'icon': {
      // An iconify id, read off the record or fixed; nothing to draw without one.
      const bound = el.bind ? resolvePath(node, el.bind) : undefined;
      const id = typeof bound === 'string' && bound !== '' ? bound : el.icon;
      if (!id) return [];
      const fill =
        lookupColor(el.colorLookup, el.colorRole, el.color, node, palette) ??
        palette.foreground ??
        0x111111;
      return [
        {
          part: 'icon',
          x: el.x,
          y: el.y,
          size: el.size,
          icon: {
            kind: 'svg-url',
            url: `https://api.iconify.design/${id}.svg`,
            color: fill,
            ...(el.strokeWidth !== undefined ? { strokeWidth: el.strokeWidth } : {}),
          },
        },
      ];
    }
    default:
      return [];
  }
}
